{
  "title": "The Gilded Chain: Rescue in Ruinfall",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "A lone scout peers at the ruined city from a ridge.",
      "visual_description": "Dawn light breaks over crumbling spires and collapsed walls. Tattered royal banners flap in the wind. The scout crouches behind a mossy stone, studying the silent city.",
      "characters": ["scout"]
    },
    {
      "scene_number": 2,
      "caption": "The scout reports to the rescue party in a hidden camp.",
      "visual_description": "A campfire flickers among the ruins of an old mill. The scout gestures toward the city while a knight, a mage, and a rogue listen intently. Armor gleams dully in the firelight.",
      "characters": ["scout", "knight", "mage", "rogue"]
    },
    {
      "scene_number": 3,
      "caption": "Frightened townspeople whisper warnings at the city's edge.",
      "visual_description": "Huddled near a broken well, townspeople in ragged clothes clutch children and baskets. One old woman points a trembling hand toward the distant castle. Fear is in their eyes.",
      "characters": ["old woman", "townspeople"]
    },
    {
      "scene_number": 4,
      "caption": "The party enters through the cracked castle gates.",
      "visual_description": "Massive iron gates stand ajar, one hinge broken. The knight pushes the left door open while the mage lights a glowing orb. Dust and shadows spill out.",
      "characters": ["knight", "mage", "rogue"]
    },
    {
      "scene_number": 5,
      "caption": "Armored patrols march through a courtyard.",
      "visual_description": "A company of armored soldiers in faded livery marches in lockstep, their faces hidden behind visors. The party hides behind a collapsed colonnade, watching.",
      "characters": ["knight", "mage", "rogue", "armored patrols"]
    },
    {
      "scene_number": 6,
      "caption": "A magic door blocks the path to the inner keep.",
      "visual_description": "A stone door carved with glowing runes pulses with blue light. Strange symbols spiral outward. The mage steps forward, hand raised, studying the enchantment.",
      "characters": ["mage", "knight", "rogue"]
    },
    {
      "scene_number": 7,
      "caption": "The mage disarms the door's riddle trap.",
      "visual_description": "The mage traces a pattern in the air. The runes flicker, then fade. The door grinds open to reveal a dark corridor beyond.",
      "characters": ["mage", "knight", "rogue"]
    },
    {
      "scene_number": 8,
      "caption": "A cursed tower looms above a ruined chapel.",
      "visual_description": "A twisted black spire leans over a roofless chapel. Strange whispers seem to emanate from its windows. The rogue peers up, one hand on a dagger.",
      "characters": ["rogue", "knight", "mage"]
    },
    {
      "scene_number": 9,
      "caption": "Rumors of a dragon echo from a tavern cellar.",
      "visual_description": "In a dim cellar tavern, a grizzled man leans over a barrel, spreading his hands wide. The party listens as he describes a dragon seen circling the old keep.",
      "characters": ["grizzled man", "knight", "mage", "rogue"]
    },
    {
      "scene_number": 10,
      "caption": "The party climbs the cursed tower's winding stair.",
      "visual_description": "Narrow stone steps spiral upward. Cobwebs brush their faces. The knight's torch throws long, wavering shadows. A faint, rhythmic thumping comes from above.",
      "characters": ["knight", "mage", "rogue"]
    },
    {
      "scene_number": 11,
      "caption": "They find the captive in a high chamber.",
      "visual_description": "A single figure in torn robes stands chained to a pillar near a window. Moonlight streams in. The captive looks up, eyes wide with hope and exhaustion.",
      "characters": ["knight", "mage", "rogue", "captive"]
    },
    {
      "scene_number": 12,
      "caption": "The rogue picks the lock while the knight stands guard.",
      "visual_description": "The rogue works a set of picks into the manacles. The knight faces the door, sword drawn. The mage mutters a warding spell.",
      "characters": ["rogue", "knight", "mage", "captive"]
    },
    {
      "scene_number": 13,
      "caption": "Alarm bells ring as the escape is discovered.",
      "visual_description": "The manacles fall. From below, a bell clangs wildly. Shouts echo in the stairwell. The party freezes, then moves as one toward the tower's lower door.",
      "characters": ["captive", "rogue", "knight", "mage"]
    },
    {
      "scene_number": 14,
      "caption": "Armored patrols charge into the tower courtyard.",
      "visual_description": "Soldiers burst through an archway, swords drawn. The knight meets them with a shield bash. The mage hurls a burst of light that staggers the front rank.",
      "characters": ["knight", "mage", "rogue", "captive", "armored patrols"]
    },
    {
      "scene_number": 15,
      "caption": "The party flees through the market square.",
      "visual_description": "Stalls and awnings collapse as the party runs. The rogue kicks over a cart to slow the pursuing guards. The mage shields the captive from falling debris.",
      "characters": ["rogue", "captive", "mage", "knight"]
    },
    {
      "scene_number": 16,
      "caption": "A dragon's shadow passes overhead.",
      "visual_description": "A massive winged shape blots out the sun. The party ducks into a doorway. The dragon roars, circling the old keep, but does not descend on them.",
      "characters": ["knight", "mage", "rogue", "captive"]
    },
    {
      "scene_number": 17,
      "caption": "The final escape across a crumbling bridge.",
      "visual_description": "A stone bridge spans a deep gorge. Half the parapet is gone. The party runs across, the captive supported by the knight. Behind them, soldiers reach the bridgehead.",
      "characters": ["knight", "mage", "rogue", "captive", "armored patrols"]
    },
    {
      "scene_number": 18,
      "caption": "The bridge collapses behind them, sealing their escape.",
      "visual_description": "The mage turns and thrusts a hand forward. A crack runs through the bridge, then the span crumbles into the gorge. The party watches from the far side, safe for now.",
      "characters": ["knight", "mage", "rogue", "captive"]
    }
  ]
}

